@Test
public void testMultipleLoginOnSameBrowser() throws Exception {
    LOGGER.info("Start test testMultipleLoginOnSameBrowser");
    // Add login event condition
    ConditionType conditionType = CustomObjectMapper.getObjectMapper().readValue(new File("data/tmp/testLoginEventCondition.json").toURI().toURL(), ConditionType.class);
    definitionsService.setConditionType(conditionType);
    refreshPersistence(ConditionType.class);
    Thread.sleep(2000);
    // Add login rule
    Rule rule = CustomObjectMapper.getObjectMapper().readValue(new File("data/tmp/testLogin.json").toURI().toURL(), Rule.class);
    createAndWaitForRule(rule);
    CustomItem sourceSite = new CustomItem(ITEM_ID_SITE, ITEM_TYPE_SITE);
    sourceSite.setScope(TEST_SCOPE);
    // First page view with the first visitor aka VISITOR_1 and SESSION_ID_3
    ContextRequest contextRequestPageViewSession1 = getContextRequestWithPageViewEvent(sourceSite, SESSION_ID_3);
    HttpPost requestPageView1 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestPageView1.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestPageViewSession1), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponsePageView1 = executeContextJSONRequest(requestPageView1, SESSION_ID_3);
    String profileIdVisitor1 = requestResponsePageView1.getContextResponse().getProfileId();
    String lastVisit = (String) requestResponsePageView1.getContextResponse().getProfileProperties().get("lastVisit");
    Assert.assertNotNull("Context profile properties should contains a lastVisit property", lastVisit);
    Thread.sleep(1000);
    // Initialize VISITOR_1 properties
    Map<String, Object> loginEventPropertiesVisitor1 = new HashMap<>();
    loginEventPropertiesVisitor1.put(FIRST_NAME, FIRST_NAME_VISITOR_1);
    loginEventPropertiesVisitor1.put(LAST_NAME, LAST_NAME_VISITOR_1);
    loginEventPropertiesVisitor1.put(EMAIL, EMAIL_VISITOR_1);
    // Create login event with VISITOR_1
    ContextRequest contextRequestLoginVisitor1 = getContextRequestWithLoginEvent(sourceSite, loginEventPropertiesVisitor1, EMAIL_VISITOR_1, SESSION_ID_3);
    HttpPost requestLoginVisitor1 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestLoginVisitor1.addHeader("Cookie", requestResponsePageView1.getCookieHeaderValue());
    requestLoginVisitor1.addHeader("X-Unomi-Peer", UNOMI_KEY);
    requestLoginVisitor1.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestLoginVisitor1), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponseLoginVisitor1 = executeContextJSONRequest(requestLoginVisitor1, SESSION_ID_3);
    Assert.assertEquals("Context profile id should be the same", profileIdVisitor1, requestResponseLoginVisitor1.getContextResponse().getProfileId());
    checkVisitor1ResponseProperties(requestResponseLoginVisitor1.getContextResponse().getProfileProperties());
    Assert.assertEquals("LastVisit property should not be updated as we are on the same session", lastVisit, requestResponseLoginVisitor1.getContextResponse().getProfileProperties().get("lastVisit"));
    Thread.sleep(1000);
    // Lets add a page view with VISITOR_1 to simulate reloading the page after login and be able to check the profile properties
    HttpPost requestPageView2 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestPageView2.addHeader("Cookie", requestResponsePageView1.getCookieHeaderValue());
    requestPageView2.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestPageViewSession1), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponsePageView2 = executeContextJSONRequest(requestPageView2, SESSION_ID_3);
    Assert.assertEquals("Context profile id should be the same", profileIdVisitor1, requestResponsePageView2.getContextResponse().getProfileId());
    checkVisitor1ResponseProperties(requestResponsePageView2.getContextResponse().getProfileProperties());
    Assert.assertEquals("LastVisit property should not be updated as we are on the same session", lastVisit, requestResponsePageView2.getContextResponse().getProfileProperties().get("lastVisit"));
    Thread.sleep(1000);
    // Lets simulate a logout by requesting the context with a new page view event and a new session id
    // but we will send the cookie of the profile id from VISITOR_1
    ContextRequest contextRequestPageViewSession2 = getContextRequestWithPageViewEvent(sourceSite, SESSION_ID_4);
    HttpPost requestPageView3 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestPageView3.addHeader("Cookie", requestResponsePageView1.getCookieHeaderValue());
    requestPageView3.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestPageViewSession2), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponsePageView3 = executeContextJSONRequest(requestPageView3, SESSION_ID_4);
    Assert.assertEquals("Context profile id should be the same", profileIdVisitor1, requestResponsePageView3.getContextResponse().getProfileId());
    checkVisitor1ResponseProperties(requestResponsePageView3.getContextResponse().getProfileProperties());
    Assert.assertEquals("previousVisit property should be updated as we are on a new session", lastVisit, requestResponsePageView3.getContextResponse().getProfileProperties().get("previousVisit"));
    Assert.assertNotEquals("lastVisit property should be updated as we are on a new session", lastVisit, requestResponsePageView3.getContextResponse().getProfileProperties().get("lastVisit"));
    lastVisit = (String) requestResponsePageView3.getContextResponse().getProfileProperties().get("lastVisit");
    Assert.assertNotNull("Context profile properties should contains a lastVisit property", lastVisit);
    Thread.sleep(1000);
    // Initialize VISITOR_2 properties
    Map<String, Object> loginEventPropertiesVisitor2 = new HashMap<>();
    loginEventPropertiesVisitor2.put(FIRST_NAME, FIRST_NAME_VISITOR_2);
    loginEventPropertiesVisitor2.put(LAST_NAME, LAST_NAME_VISITOR_2);
    loginEventPropertiesVisitor2.put(EMAIL, EMAIL_VISITOR_2);
    // Create login event with VISITOR_2
    ContextRequest contextRequestLoginVisitor2 = getContextRequestWithLoginEvent(sourceSite, loginEventPropertiesVisitor2, EMAIL_VISITOR_2, SESSION_ID_4);
    HttpPost requestLoginVisitor2 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestLoginVisitor2.addHeader("Cookie", requestResponsePageView1.getCookieHeaderValue());
    requestLoginVisitor2.addHeader("X-Unomi-Peer", UNOMI_KEY);
    requestLoginVisitor2.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestLoginVisitor2), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponseLoginVisitor2 = executeContextJSONRequest(requestLoginVisitor2, SESSION_ID_4);
    // We should have a new profile id so the session should have been moved from VISITOR_1 to VISITOR_2
    String profileIdVisitor2 = requestResponseLoginVisitor2.getContextResponse().getProfileId();
    Assert.assertNotEquals("Context profile id should not be the same", profileIdVisitor1, profileIdVisitor2);
    checkVisitor2ResponseProperties(requestResponseLoginVisitor2.getContextResponse().getProfileProperties());
    Thread.sleep(1000);
    // Lets add a page view with VISITOR_2 to simulate reloading the page after login
    HttpPost requestPageView4 = new HttpPost(getFullUrl("/cxs/context.json"));
    requestPageView4.addHeader("Cookie", requestResponseLoginVisitor2.getCookieHeaderValue());
    requestPageView4.setEntity(new StringEntity(objectMapper.writeValueAsString(contextRequestPageViewSession2), ContentType.create("application/json")));
    TestUtils.RequestResponse requestResponsePageView4 = executeContextJSONRequest(requestPageView4, SESSION_ID_4);
    Assert.assertEquals("Context profile id should be the same", profileIdVisitor2, requestResponsePageView4.getContextResponse().getProfileId());
    checkVisitor2ResponseProperties(requestResponsePageView4.getContextResponse().getProfileProperties());
    Thread.sleep(1000);
    refreshPersistence(Profile.class);
    // Check both visitor profile at the end by loading them directly
    Profile profileVisitor1 = profileService.load(profileIdVisitor1);
    checkVisitor1ResponseProperties(profileVisitor1.getProperties());
    Profile profileVisitor2 = profileService.load(profileIdVisitor2);
    checkVisitor2ResponseProperties(profileVisitor2.getProperties());
    LOGGER.info("End test testMultipleLoginOnSameBrowser");
}

@Test
public void testCompound() {
    // test AND
    assertTrue(eval(builder.and(builder.profileProperty("properties.gender").equalTo("female"), builder.profileProperty("properties.age").equalTo(30)).build()));
    assertFalse(eval(builder.and(builder.profileProperty("properties.gender").equalTo("male"), builder.profileProperty("properties.age").equalTo(30)).build()));
    assertFalse(eval(builder.and(builder.profileProperty("properties.gender").equalTo("female"), builder.profileProperty("properties.age").equalTo(40)).build()));
    // test OR
    assertTrue(eval(builder.or(builder.profileProperty("properties.gender").equalTo("female"), builder.profileProperty("properties.age").equalTo(40)).build()));
    assertTrue(eval(builder.or(builder.profileProperty("properties.gender").equalTo("male"), builder.profileProperty("properties.age").equalTo(30)).build()));
    assertFalse(eval(builder.or(builder.profileProperty("properties.gender").equalTo("male"), builder.profileProperty("properties.age").equalTo(40)).build()));
    // test NOT
    assertTrue(eval(builder.not(builder.profileProperty("properties.gender").equalTo("male")).build()));
    assertFalse(eval(builder.not(builder.profileProperty("properties.age").equalTo(30)).build()));
}

@Test
public void testDate() {
    assertTrue(eval(builder.profileProperty("properties.lastVisit").equalTo(lastVisit).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").greaterThan(new Date(lastVisit.getTime() - 10000)).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").lessThan(new Date(lastVisit.getTime() + 10000)).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").in(new Date(lastVisit.getTime() + 10000), new Date(lastVisit.getTime() - 10000), lastVisit).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").notIn(new Date(lastVisit.getTime() + 10000), new Date(lastVisit.getTime() - 10000)).build()));
    assertFalse(eval(builder.profileProperty("properties.lastVisit").notIn(new Date(lastVisit.getTime() + 10000), new Date(lastVisit.getTime() - 10000), lastVisit).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").all(lastVisit).build()));
    assertFalse(eval(builder.profileProperty("properties.lastVisit").all(new Date(lastVisit.getTime() + 10000), lastVisit).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").isDay(lastVisit).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").isNotDay(new Date(lastVisit.getTime() + (24 * 60 * 60 * 1000))).build()));
    // we add one hour to the current time to compensate for differences due to Daylight Saving Time.
    long daysFromToday = TimeUnit.MILLISECONDS.toDays(DateUtils.truncate(new Date(), Calendar.DAY_OF_MONTH).getTime() + 60 * 60 * 1000 - DateUtils.truncate(lastVisit, Calendar.DAY_OF_MONTH).getTime());
    assertTrue(eval(builder.profileProperty("properties.lastVisit").isDay("now-" + daysFromToday + "d").build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").isNotDay("now-" + (daysFromToday + 1) + "d").build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").inDateExpr("" + lastVisit.getTime()).build()));
    assertTrue(eval(builder.profileProperty("properties.lastVisit").notInDateExpr("now-" + (daysFromToday + 1) + "d").build()));
}

@Test
public void testExistence() {
    assertTrue("Gender property does not exist", eval(builder.profileProperty("properties.gender").exists().build()));
    assertFalse("Gender property missing", eval(builder.profileProperty("properties.gender").missing().build()));
    assertTrue("Strange property exists", eval(builder.profileProperty("properties.unknown").missing().build()));
