    // this is required for Windows support
    vulnFileCanonicalPath = vulnFileCanonicalPath.replace("\\", "\\\\");
    Map<String, String> parameters = new HashMap<>();
    parameters.put("VULN_FILE_PATH", vulnFileCanonicalPath);
    HttpPost request = new HttpPost(getFullUrl(CONTEXT_URL));
    request.setEntity(new StringEntity(getValidatedBundleJSON("security/ognl-payload-1.json", parameters), ContentType.APPLICATION_JSON));
    TestUtils.executeContextJSONRequest(request);
    shouldBeTrueUntilEnd("Vulnerability successfully executed ! File created at " + vulnFileCanonicalPath, vulnFile::exists, exists -> exists == Boolean.FALSE, DEFAULT_TRYING_TIMEOUT, DEFAULT_TRYING_TRIES);
}

